#!/bin/bash
# Resubmit qld_full40 stage5 work (walltime 26520867) + nonmand (OOM 26520869).
# Adds EXTRA_ENV=STAGE5_LARCH_LOGSUM=0 so the 371-zone Larch loop is skipped.
# -v value is double-quoted (GA_S4_VARIANTS uses ; separator).
# Usage: bash resubmit_qld_full40_work_nonmand.sh   (run on a login node from code/)
set -euo pipefail
cd /mnt/hpccs01/home/ahernz/test_runs_tours/code
qsub -P FPAXJW8067 -N ga_s5work_qld_full40 -l select=1:ncpus=4:mem=96GB -l walltime=24:00:00 -v "RUN_ROOT=runs/ga_parallel,RUN_TAG=qld_full40,CONDA_ENV=zigenv,GA_BUDGET=ultrafast,GA_ESTIMATOR=metacount_mv,GA_ENGINE=agds,GA_N_RESTARTS=0,GA_PARALLEL_SEGMENTS=1,GA_SHARD_VARIANTS=1,GA_S4_VARIANTS=rrm;tdd,GA_STAGE4_MXL_SEARCH=0,GA_STAGE4_GENS=,GA_STAGE4_RESTARTS=,GA_STAGE4_EARLY_STOP=1,GA_STAGE4_EARLY_STOP_PATIENCE=120,GA_STAGE4_EARLY_STOP_MIN_GENS=120,GA_SA2_GENS=,GA_SA2_RESTARTS=,STAGE2_MH=0,STAGE2_MH_BURN=1000,STAGE2_MH_DRAWS=2000,STAGE2_MH_THIN=2,STAGE2_MH_SEED=42,STAGE2_MH_PROPOSAL_SCALE=1.0,GA_S5_MODE_VARIANTS=nl;mnl;lccm,GA_S5_DEST_VARIANTS=mnl;nl_dist,GA_STAGE5_GENS=40,GA_STAGE5_RESTARTS=1,GA_STAGE0_GENS=,GA_STAGE0_RESTARTS=,GA_STAGE51_GENS=,GA_STAGE51_RESTARTS=,GA_STAGE5_STAG=,GA_WALLTIME_MARGIN_SECONDS=300,GA_STAGE5_RUN_MODE=1,GA_STAGE5_RUN_DEST=1,GA_SEED=,GA_L1_L2_ALPHA=1e-3,STAGE5B_CA_FULLGRID_CASES=1500,CDAP_MXL=0,CDAP_MXL_DRAWS=50,CDAP_MXL_MAX_N=2000,CDAP_MH_BURN=1000,CDAP_MH_DRAWS=2000,CDAP_MH_THIN=5,CDAP_MH_SEED=42,CDAP_MH_PRIOR_SD=5.0,NEW_POP=1,NEW_POP_MAPPED=0,NEW_POP_DIR=../new_pop,PIPELINE_SKIMS_PATH=../demand_/skims_371.omx,EXTRA_ENV=STAGE5_LARCH_LOGSUM=0,STAGE_ID=5,SHARD_SEGMENT=work,GA_WALLTIME_SECONDS=86400,GA_JAX_CACHE_MEM_LIMIT_GB=96,GA_JAX_CACHE_CHECK_EVERY=10,STAGE5_DEST_SAMPLE_SIZE=20" job_ga_shard_single.pbs
